// Language: Verilog 2001

`resetall
`timescale 1ns / 1ps
`default_nettype none

/*
 * Simple IEEE 802.3 clause 22 MDIO master.
 *
 * MDC is generated by dividing clk by 2*CLK_DIV.  The MDIO line is
 * open-drain: mdio_oe=1 drives a 0, mdio_oe=0 releases the line and lets
 * the PHY pull-up (or the PHY itself for a read) drive it high.
 */
module mdio_master #(
    parameter CLK_DIV = 25
)(
    input  wire        clk,
    input  wire        rst,

    input  wire        start,
    input  wire [4:0]  phy_addr,
    input  wire [4:0]  reg_addr,
    input  wire [15:0] write_data,
    input  wire        write_en,

    output reg         busy,
    output reg         done,
    output reg  [15:0] read_data,

    output reg         mdc,
    output reg         mdio_oe,
    output wire        mdio_o,
    input  wire        mdio_i
);

localparam [1:0] OP_READ  = 2'b10;
localparam [1:0] OP_WRITE = 2'b01;

reg [5:0]  clk_div;
reg [6:0]  bit_idx;
reg [63:0] tx_frame;
reg [15:0] rx_shift;
reg        mdc_fall;
reg        mdc_rise;

// open-drain output: only ever drive low
assign mdio_o = 1'b0;

always @* begin
    mdc_fall = 1'b0;
    mdc_rise = 1'b0;
    if (busy && clk_div == CLK_DIV-1) begin
        if (mdc)
            mdc_fall = 1'b1;
        else
            mdc_rise = 1'b1;
    end
end

always @* begin
    mdio_oe = 1'b0;
    if (busy) begin
        if (write_en) begin
            mdio_oe = ~tx_frame[63];
        end else begin
            // release during turnaround and read data
            if (bit_idx < 7'd46)
                mdio_oe = ~tx_frame[63];
            else
                mdio_oe = 1'b0;
        end
    end
end

always @(posedge clk) begin
    if (rst) begin
        busy <= 1'b0;
        done <= 1'b0;
        read_data <= 16'd0;
        mdc <= 1'b0;
        clk_div <= 6'd0;
        bit_idx <= 7'd0;
        tx_frame <= 64'd0;
        rx_shift <= 16'd0;
    end else begin
        done <= 1'b0;

        if (start && !busy) begin
            busy <= 1'b1;
            clk_div <= 6'd0;
            mdc <= 1'b0;
            bit_idx <= 7'd0;
            rx_shift <= 16'd0;
            if (write_en)
                tx_frame <= {32'hFFFFFFFF, 2'b01, OP_WRITE, phy_addr, reg_addr, 2'b10, write_data};
            else
                tx_frame <= {32'hFFFFFFFF, 2'b01, OP_READ,  phy_addr, reg_addr, 2'b10, 16'h0000};
        end else if (busy) begin
            if (clk_div == CLK_DIV-1) begin
                clk_div <= 6'd0;
                mdc <= ~mdc;
            end else begin
                clk_div <= clk_div + 1'b1;
            end

            if (mdc_rise && !write_en && bit_idx >= 7'd48) begin
                rx_shift <= {rx_shift[14:0], mdio_i};
            end

            if (mdc_fall) begin
                tx_frame <= {tx_frame[62:0], 1'b0};
                if (bit_idx == 7'd63) begin
                    busy <= 1'b0;
                    done <= 1'b1;
                    read_data <= rx_shift;
                    mdc <= 1'b0;
                end else begin
                    bit_idx <= bit_idx + 1'b1;
                end
            end
        end
    end
end

endmodule

`resetall
